--
-- Table structure for table `employees`
--

DROP TABLE IF EXISTS `employees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `employees` (
  `EmployeeID` char(5) NOT NULL DEFAULT '',
  `ProfPic` longblob NOT NULL,
  `FirstName` varchar(30) DEFAULT NULL,
  `LastName` varchar(30) DEFAULT NULL,
  `Address` varchar(100) DEFAULT NULL,
  `City` varchar(50) DEFAULT NULL,
  `Region` varchar(50) DEFAULT NULL,
  `PostalCode` char(6) DEFAULT NULL,
  `PhoneNumber` varchar(12) DEFAULT NULL,
  `ManagerID` char(5) DEFAULT NULL,
  `JobID` char(5) DEFAULT NULL,
  `DeptID` char(5) DEFAULT NULL,
  PRIMARY KEY (`EmployeeID`),
  KEY `JobID` (`JobID`),
  KEY `DeptID` (`DeptID`),
  CONSTRAINT `employees_ibfk_1` FOREIGN KEY (`JobID`) REFERENCES `jobs` (`JobID`),
  CONSTRAINT `employees_ibfk_2` FOREIGN KEY (`DeptID`) REFERENCES `depts` (`DeptID`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `employees`
--

